// FUSE Relight RL-5.2: ReSTIR DI on the GPU (see restir_di_gpu.hpp).
#include <fuse/relight/render/pathtrace/restir_di_gpu.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by render/pathtrace/restir_di_embed.cmake: kRlRestirDi{Slang,Glsl}Spv, FUSE_RL_RESTIR_DI_{SLANG,GLSL}.
#include "rl_restir_di_spv.h"
#endif

namespace fuse::relight::render::pathtrace {

namespace rr = fuse::renderer;
namespace rg = fuse::renderer::rg;

namespace {
constexpr u32 kGroup = 8u;
constexpr u64 kWordBytes = 16u;
constexpr u64 kBlockBytes = 128u; ///< 8 addresses + kRdiParamWords float4

u64 align256(u64 v) { return (v + 255u) & ~u64{255u}; }

u32 storageUsage() {
    return static_cast<u32>(rr::BufferUsage::Storage) | static_cast<u32>(rr::BufferUsage::ShaderDeviceAddress) |
           static_cast<u32>(rr::BufferUsage::TransferSrc);
}

constexpr const char* kSectionNames[kRdiSections] = {
    "relight.restir_di.surfaces0", "relight.restir_di.surfaces1", "relight.restir_di.initial",
    "relight.restir_di.a",         "relight.restir_di.b",         "relight.restir_di.history",
    "relight.restir_di.output",    "relight.restir_di.tiles"};

enum StageId : u32 {
    kStagePresample = 0u,
    kStageSurface = 1u,
    kStageInitial = 2u,
    kStageTemporal = 3u,
    kStageShade = 4u,
    kStageSpatial = 8u,
};
} // namespace

RestirDiGpu::RestirDiGpu() = default;
RestirDiGpu::~RestirDiGpu() { destroy(); }

bool RestirDiGpu::init(const RestirDiGpuDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.device == nullptr || desc.allocator == nullptr || desc.bindless == nullptr || desc.framesInFlight == 0u ||
        desc.framesInFlight > kMaxSlots) {
        m_reason = "incomplete RestirDiGpuDesc";
        return false;
    }
    m_retired.reserve(32);
    m_initialized = true;
    if (!createPipeline()) {
        m_reason = "no ReSTIR DI kernel of the requested language / pipeline creation failed";
        destroy();
        return false;
    }
    m_reason = "ok";
    return true;
#else
    m_reason = "stub backend";
    return false;
#endif
}

void RestirDiGpu::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    for (rr::Buffer& b : m_sections) {
        if (b.handle != nullptr) {
            m_desc.allocator->destroyBuffer(b);
        }
        b = rr::Buffer{};
    }
    if (m_ring.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_ring);
    }
    m_ring = rr::Buffer{};
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    if (m_pipeline != nullptr) {
        vkDestroyPipeline(device, static_cast<VkPipeline>(m_pipeline), nullptr);
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_pipeline = nullptr;
    m_layoutHandle = nullptr;
    m_retired.clear();
    for (u64& b : m_sectionBytes) {
        b = 0;
    }
    m_slotStride = 0;
    m_width = 0;
    m_height = 0;
    m_historyValid = false;
    m_frameReady = false;
    m_language = "none";
    m_stats = RestirDiGpuStats{};
    m_initialized = false;
}

bool RestirDiGpu::createPipeline() {
#if defined(FUSE_VULKAN_BACKEND)
    const u32* words = nullptr;
    usize bytes = 0;
#if defined(FUSE_RL_RESTIR_DI_SLANG)
    if (m_desc.language == PtKernelLanguage::Auto || m_desc.language == PtKernelLanguage::Slang) {
        words = kRlRestirDiSlangSpv;
        bytes = sizeof(kRlRestirDiSlangSpv);
        m_language = "slang";
    }
#endif
#if defined(FUSE_RL_RESTIR_DI_GLSL)
    if (words == nullptr && (m_desc.language == PtKernelLanguage::Auto || m_desc.language == PtKernelLanguage::Glsl)) {
        words = kRlRestirDiGlslSpv;
        bytes = sizeof(kRlRestirDiGlslSpv);
        m_language = "glsl";
    }
#endif
    if (words == nullptr) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, static_cast<u32>(sizeof(Push))};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = 1u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    VkShaderModuleCreateInfo moduleInfo{};
    moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    moduleInfo.codeSize = bytes;
    moduleInfo.pCode = words;
    VkShaderModule module = VK_NULL_HANDLE;
    if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
        return false;
    }
    VkComputePipelineCreateInfo info{};
    info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
    info.flags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
    info.stage.module = module;
    info.stage.pName = "main";
    info.layout = layout;
    VkPipeline pipeline = VK_NULL_HANDLE;
    const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
    vkDestroyShaderModule(device, module, nullptr);
    m_pipeline = pipeline;
    return result == VK_SUCCESS;
#else
    return false;
#endif
}

bool RestirDiGpu::ensureBuffer(rr::Buffer& buffer, u64 bytes, u32 memory, const char* name, u8* queue) {
    if (buffer.handle != nullptr && bytes <= buffer.desc.size) {
        return true;
    }
    rr::BufferDesc d{};
    d.size = static_cast<usize>(bytes);
    d.usage = static_cast<rr::BufferUsage>(storageUsage());
    d.memoryUsage = static_cast<rr::MemoryUsage>(memory);
    d.name = name;
    rr::Buffer fresh{};
    if (!m_desc.allocator->createBuffer(d, fresh) || fresh.mapped == nullptr || fresh.deviceAddress == 0u) {
        if (fresh.handle != nullptr) {
            m_desc.allocator->destroyBuffer(fresh);
        }
        return false;
    }
    if (buffer.handle != nullptr) {
        m_retired.push_back(Retired{buffer, m_frameSerial});
        ++m_stats.reallocations;
    }
    buffer = fresh;
    if (queue != nullptr) {
        *queue = rg::kNoQueue;
    }
    return true;
}

bool RestirDiGpu::beginFrame(u64 frameSerial, const PtCompiledScene& scene, const PtFrameDesc& frame,
                             const RestirDiSettings& settings) {
    m_frameReady = false;
    if (!m_initialized || !scene.valid() || frame.width == 0u || frame.height == 0u) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_settings = settings;
    m_stats.passes = 0;
    const bool resized = frame.width != m_width || frame.height != m_height;
    m_width = frame.width;
    m_height = frame.height;
    // Light table and tiles.
    const bool usable = m_table.build(scene, settings.distantArea);
    m_tileCount = usable && settings.tileCandidates > 0u && settings.tileSize > 0u ? settings.tileCount : 0u;
    // Persistent sections.
    const u64 pixels = u64(frame.width) * frame.height;
    u64 want[kRdiSections];
    want[kRdiSecSurface0] = pixels * kRdiSurfaceWords * kWordBytes;
    want[kRdiSecSurface1] = want[kRdiSecSurface0];
    for (u32 s = kRdiSecInitial; s <= kRdiSecHistory; ++s) {
        want[s] = pixels * kRdiReservoirWords * kWordBytes;
    }
    want[kRdiSecOutput] = pixels * kRdiOutWords * kWordBytes;
    want[kRdiSecTiles] = std::max<u64>(u64(m_tileCount) * settings.tileSize * sizeof(u32), 16u);
    bool reallocated = false;
    for (u32 s = 0; s < kRdiSections; ++s) {
        const bool had = m_sections[s].handle != nullptr;
        const u64 before = had ? m_sections[s].desc.size : 0u;
        if (!ensureBuffer(m_sections[s], align256(want[s]), static_cast<u32>(rr::MemoryUsage::GpuToCpu),
                          kSectionNames[s], &m_sectionQueues[s])) {
            m_reason = "ReSTIR DI section buffer";
            return false;
        }
        reallocated = reallocated || !had || m_sections[s].desc.size != before;
        m_sectionBytes[s] = want[s];
    }
    if (resized || reallocated) {
        m_historyValid = false;
    }
    // Ring slot: block, pmf, cdf.
    const u64 lights = std::max<u64>(m_table.lightCount(), 1u);
    const u64 pmfOffset = align256(kBlockBytes);
    const u64 cdfOffset = pmfOffset + align256(lights * sizeof(float));
    const u64 slotBytes = cdfOffset + align256(lights * sizeof(float));
    if (m_ring.handle == nullptr || slotBytes > m_slotStride) {
        const u64 stride = align256(std::max<u64>(slotBytes + slotBytes / 2u, 4096u));
        if (m_ring.handle != nullptr) {
            m_retired.push_back(Retired{m_ring, frameSerial});
            m_ring = rr::Buffer{};
            ++m_stats.reallocations;
        }
        if (!ensureBuffer(m_ring, stride * m_desc.framesInFlight, static_cast<u32>(rr::MemoryUsage::CpuToGpu),
                          "relight.restir_di.ring", &m_ringQueue)) {
            m_reason = "ReSTIR DI ring";
            return false;
        }
        m_slotStride = stride;
    }
    m_slot = static_cast<u32>(frameSerial % m_desc.framesInFlight);
    m_slotBytes = slotBytes;
    m_blockOffset = u64(m_slot) * m_slotStride;
    m_cur ^= 1u;
    m_flags = (settings.unbiased ? kRdiFlagUnbiased : 0u) | (m_historyValid ? kRdiFlagHistory : 0u) |
              (settings.initialVisibility ? kRdiFlagInitialVisibility : 0u) |
              (settings.temporal ? kRdiFlagTemporal : 0u);
    u8* slot = static_cast<u8*>(m_ring.mapped) + m_blockOffset;
    const u64 slotAddress = m_ring.deviceAddress + m_blockOffset;
    const u32 curSec = m_cur == 0u ? kRdiSecSurface0 : kRdiSecSurface1;
    const u32 prevSec = m_cur == 0u ? kRdiSecSurface1 : kRdiSecSurface0;
    u64 block[8] = {m_sections[curSec].deviceAddress,
                    m_sections[prevSec].deviceAddress,
                    m_sections[kRdiSecHistory].deviceAddress,
                    m_sections[kRdiSecTiles].deviceAddress,
                    slotAddress + pmfOffset,
                    slotAddress + cdfOffset,
                    m_sections[kRdiSecOutput].deviceAddress,
                    0u};
    std::memcpy(slot, block, sizeof(block));
    Word params[kRdiParamWords];
    packRestirDiParams(settings, m_flags, m_tileCount, 0u, params);
    std::memcpy(slot + 64u, params, sizeof(params));
    if (m_table.lightCount() > 0u) {
        std::memcpy(slot + pmfOffset, m_table.pmf().data(), m_table.lightCount() * sizeof(float));
        std::memcpy(slot + cdfOffset, m_table.cdf().data(), m_table.lightCount() * sizeof(float));
    }
    m_frameReady = true;
    ++m_stats.frames;
    return true;
}

bool RestirDiGpu::addPasses(rg::Graph& graph, PathTracerGpu& pt, const PtGraphRefs& ptRefs) {
    if (!m_initialized || !m_frameReady || !ptRefs.valid) {
        return false;
    }
    if (!pt.addLightsPass(graph, ptRefs)) {
        m_reason = "light convert pass";
        return false;
    }
    const PtTraceBindings b = pt.traceBindings();
    if (b.width != m_width || b.height != m_height || b.params == 0u) {
        m_reason = "PathTracerGpu frame does not match";
        return false;
    }
    m_refs = RestirDiGraphRefs{};
    for (u32 s = 0; s < kRdiSections; ++s) {
        m_refs.sections[s] = graph.importBuffer(rg::ImportedBuffer{
            m_sections[s].handle, m_sections[s].desc.size, m_sectionQueues[s], &m_sectionQueues[s], kSectionNames[s]});
    }
    m_refs.ring = graph.importBuffer(
        rg::ImportedBuffer{m_ring.handle, m_ring.desc.size, m_ringQueue, &m_ringQueue, "relight.restir_di.ring"});
    m_refs.ringRange = rg::BufferRange{m_blockOffset, m_slotBytes};
    m_refs.valid = true;

    Push base{};
    base.params = b.params;
    base.instances = b.instances;
    base.triangles = b.triangles;
    base.materials = b.materials;
    base.portals = b.portals;
    base.lightMap = b.lightMap;
    base.lightTable = ptRefs.lights.tableAddress;
    base.lightTree = ptRefs.lights.tree.header;
    base.tlas = b.tlas;
    base.lut = b.lut;
    base.block = m_ring.deviceAddress + m_blockOffset;
    base.width = m_width;
    base.height = m_height;
    base.lightCount = b.lightCount;
    const u32 curSec = currentSurfaceSection();
    const u32 prevSec = curSec == kRdiSecSurface0 ? kRdiSecSurface1 : kRdiSecSurface0;
    auto range = [&](u32 s) { return rg::BufferRange{0u, m_sectionBytes[s]}; };
    auto addr = [&](u32 s) { return m_sections[s].deviceAddress; };
    u32 count = 0;
    auto add = [&](const char* name, u32 stage, u64 src, u64 dst, u32 w, u32 h, bool scene) -> rg::PassBuilder {
        PassRecord& r = m_records[count++];
        r = PassRecord{};
        r.self = this;
        r.push = base;
        r.push.stage = stage;
        r.push.src = src;
        r.push.dst = dst;
        r.push.width = w;
        r.push.height = h;
        r.groupsX = (w + kGroup - 1u) / kGroup;
        r.groupsY = (h + kGroup - 1u) / kGroup;
        ++m_stats.passes;
        rg::PassBuilder pass = graph.addPass(name, &RestirDiGpu::record, &r);
        pass.use(ptRefs.ring, rg::Access::StorageRead, ptRefs.ringRange, rg::kStageCompute)
            .use(m_refs.ring, rg::Access::StorageRead, m_refs.ringRange, rg::kStageCompute);
        if (scene) {
            pass.use(ptRefs.rt.tlas, rg::Access::AccelerationStructureRead, {}, rg::kStageCompute)
                .use(ptRefs.statics, rg::Access::StorageRead, {}, rg::kStageCompute)
                .use(ptRefs.lights.ring, rg::Access::StorageRead, ptRefs.lights.tableRange, rg::kStageCompute);
            if (ptRefs.lights.tree.tree.valid()) {
                pass.use(ptRefs.lights.tree.tree, rg::Access::StorageRead, ptRefs.lights.tree.range,
                         rg::kStageCompute);
            }
        }
        return pass;
    };
    auto read = [&](rg::PassBuilder& pass, u32 s) {
        pass.use(m_refs.sections[s], rg::Access::StorageRead, range(s), rg::kStageCompute);
    };
    auto write = [&](rg::PassBuilder& pass, u32 s) {
        pass.use(m_refs.sections[s], rg::Access::StorageWrite, range(s), rg::kStageCompute);
    };
    if (m_tileCount > 0u) {
        rg::PassBuilder p = add("relight.restir_di.presample", kStagePresample, 0u, addr(kRdiSecTiles),
                                m_settings.tileSize, m_tileCount, false);
        write(p, kRdiSecTiles);
    }
    {
        rg::PassBuilder p = add("relight.restir_di.surface", kStageSurface, 0u, addr(curSec), m_width, m_height, true);
        write(p, curSec);
    }
    {
        rg::PassBuilder p =
            add("relight.restir_di.initial", kStageInitial, 0u, addr(kRdiSecInitial), m_width, m_height, true);
        read(p, curSec);
        read(p, kRdiSecTiles);
        write(p, kRdiSecInitial);
    }
    {
        rg::PassBuilder p = add("relight.restir_di.temporal", kStageTemporal, addr(kRdiSecInitial), addr(kRdiSecA),
                                m_width, m_height, true);
        read(p, curSec);
        read(p, prevSec);
        read(p, kRdiSecInitial);
        read(p, kRdiSecHistory);
        write(p, kRdiSecA);
    }
    u32 src = kRdiSecA;
    u32 dst = kRdiSecB;
    const u32 iterations = m_settings.spatialSamples > 0u ? std::min(m_settings.spatialIterations, 4u) : 0u;
    for (u32 it = 0; it < iterations; ++it) {
        rg::PassBuilder p =
            add("relight.restir_di.spatial", kStageSpatial + it, addr(src), addr(dst), m_width, m_height, true);
        read(p, curSec);
        read(p, src);
        write(p, dst);
        std::swap(src, dst);
    }
    m_final = src;
    {
        rg::PassBuilder p = add("relight.restir_di.shade", kStageShade, addr(src), 0u, m_width, m_height, true);
        read(p, curSec);
        read(p, src);
        write(p, kRdiSecOutput);
        write(p, kRdiSecHistory);
    }
    pt.setRestirDi(addr(kRdiSecOutput), m_refs.sections[kRdiSecOutput], range(kRdiSecOutput));
    m_historyValid = true;
    return true;
}

void RestirDiGpu::record(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const RestirDiGpu& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipeline));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0,
                       static_cast<u32>(sizeof(Push)), &r.push);
    vkCmdDispatch(cmd, r.groupsX, r.groupsY, 1u);
#else
    (void)context;
    (void)user;
#endif
}

u32 RestirDiGpu::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        if (m_retired[i].buffer.handle != nullptr) {
            m_desc.allocator->destroyBuffer(m_retired[i].buffer);
        }
        ++collected;
    }
    m_retired.resize(keep);
    return collected;
}

const void* RestirDiGpu::mappedSection(u32 section) const {
    return section < kRdiSections ? m_sections[section].mapped : nullptr;
}

} // namespace fuse::relight::render::pathtrace
